/* ================= [KD] السلايدر: حركة دائرية متصلة (بعد الأخيرة تأتي الأولى من نفس الجهة بلا رجوع سريع) + نقاط تنقل - JS: كتلة kSld في آخر القالب
   الحركة القديمة بـ CSS (tonext / tostart) تعود من الأخيرة إلى الأولى مرورا بكل الصور، فعطلناها حين يعمل السكربت ================= */
.sldO.kSld .sldS,.Rtl .sldO.kSld .sldS,.sldO.kSld .widget:last-child .sldS,.Rtl .sldO.kSld .widget:last-child .sldS{animation:none!important}
.kSldD{display:flex;justify-content:center;gap:2px;margin:8px 0 0}
.kSldD button{position:relative;width:24px;height:24px;padding:0;border:0;background:transparent;cursor:pointer}
.kSldD button::before{content:'';position:absolute;top:50%;left:50%;width:8px;height:8px;border-radius:8px;background:var(--kSrL);transform:translate(-50%,-50%);transition:width .3s,background .3s}
.kSldD button[aria-current='true']::before{width:22px;background:var(--kAcc)}
.kSldD button:hover::before{background:color-mix(in srgb,var(--kAcc) 55%,var(--kSrL))}
.kSldD button:focus-visible{outline:2px solid var(--kAcc);outline-offset:-2px;border-radius:8px}

/* ================= [KD] الشريط السفلي في الهاتف

/* ---------- [KD] السلايدر kSld: يتقدم كل 5 ثوان في اتجاه واحد دائما. نسخة من الشريحة الأولى في آخره تجعل الانتقال من الأخيرة إلى الأولى متصلا
   يتوقف عند مرور الفأرة أو اللمس أو تركيز لوحة المفاتيح أو خروجه من الشاشة. السحب باليد يبقى كما هو ---------- */
(function(){
  var o=document.querySelector('#slider-widget.sldO'); if(!o) return;
  var ws=[].filter.call(o.children,function(c){return c.classList.contains('widget')}); if(ws.length<2) return;
  var n=ws.length,DELAY=5000,cl=ws[0].cloneNode(true);
  cl.removeAttribute('id'); [].forEach.call(cl.querySelectorAll('[id]'),function(e){e.removeAttribute('id')});
  cl.setAttribute('aria-hidden','true'); cl.classList.add('kSldClone');
  [].forEach.call(cl.querySelectorAll('a,button'),function(a){a.tabIndex=-1});
  [].forEach.call(cl.querySelectorAll('[data-style]'),function(e){e.setAttribute('style',e.getAttribute('data-style'));e.classList.remove('lazy')});
  o.appendChild(cl); o.classList.add('kSld');
  var all=ws.concat([cl]),i=0,hold=false,touch=0,vis=true,t=0;
  var dots=document.createElement('div'); dots.className='kSldD';
  dots.innerHTML=ws.map(function(w,k){return "<button type='button' aria-label='الشريحة "+(k+1)+"'"+(k?"":" aria-current='true'")+"></button>"}).join('');
  o.parentNode.insertBefore(dots,o.nextSibling);
  var db=dots.querySelectorAll('button');
  function center(el){var r=el.getBoundingClientRect();return r.left+r.width/2}
  function go(k,smooth){ o.scrollBy({left:center(all[k])-center(o),behavior:smooth===false?'auto':'smooth'}); }
  function cur(){var c=center(o),best=0,d=1e9;all.forEach(function(w,k){var x=Math.abs(center(w)-c);if(x<d){d=x;best=k}});return best}
  function mark(){
    var k=cur();
    if(k===n){ var sb=o.style.scrollBehavior; o.style.scrollBehavior='auto'; go(0,false); o.style.scrollBehavior=sb; k=0; }
    i=k; [].forEach.call(db,function(b,j){ j===i?b.setAttribute('aria-current','true'):b.removeAttribute('aria-current') });
  }
  o.addEventListener('scroll',function(){ clearTimeout(t); t=setTimeout(mark,140); },{passive:true});
  [].forEach.call(db,function(b,j){ b.addEventListener('click',function(){ go(j); touch=Date.now(); }) });
  o.addEventListener('mouseenter',function(){hold=true}); o.addEventListener('mouseleave',function(){hold=false});
  o.addEventListener('touchstart',function(){touch=Date.now()},{passive:true});
  o.addEventListener('focusin',function(e){ if(e.target.matches&&e.target.matches(':focus-visible')) hold=true });
  o.addEventListener('focusout',function(){hold=false});
  if('IntersectionObserver' in window) new IntersectionObserver(function(en){vis=en[0].isIntersecting}).observe(o);
  if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  setInterval(function(){
    if(hold||!vis||document.hidden||Date.now()-touch<8000) return;
    go(i+1);
  },DELAY);
})();
